  <script>
    const faqData = [
      {
        question: "Why do cats purr?",
        answer: [
          "Cats purr when they are relaxed, but also when they are hungry, nervous, or trying to soothe themselves.",
          "Think of purring as a flexible cat communication tool rather than a single emotion."
        ]
      },
      {
        question: "How much do cats sleep?",
        answer: [
          "Most cats sleep 12 to 16 hours a day, and some even more.",
          "That nap-heavy schedule helps them conserve energy for short bursts of play and hunting behavior."
        ]
      },
      {
        question: "Do indoor cats need enrichment?",
        answer: [
          "Yes. Indoor cats stay healthier and happier when they have scratching posts, climbing spots, puzzle feeders, and daily play.",
          "A little variety goes a long way for preventing boredom."
        ]
      },
      {
        question: "Why do cats knead blankets?",
        answer: [
          "Kneading is a comforting behavior cats learn as kittens while nursing.",
          "Adult cats often knead when they feel safe, content, or ready to settle down."
        ]
      },
      {
        question: "Should I worry about slow blinking?",
        answer: [
          "No — a slow blink is usually a friendly signal that a cat feels calm.",
          "You can gently return the gesture by blinking slowly back."
        ]
      },
      {
        question: "How can I make a cat-friendly home?",
        answer: [
          "Give cats vertical space, hidey spots, fresh water, clean litter boxes, and predictable routines.",
          "The best cat homes balance safety, stimulation, and a few cozy places to disappear for a nap."
        ]
      }
    ];

    const FAQItem = ({ question, answer }) => `
      <div class="example">
        <details>
          <summary>${question}</summary>
          <div class="details">
            ${answer.map((paragraph) => `<p>${paragraph}</p>`).join("")}
          </div>
        </details>
      </div>
    `;

    const App = () => `
      <section class="hero" aria-labelledby="page-title">
        <p class="eyebrow">FAQ</p>
        <h1 id="page-title">Cat questions, answered</h1>
        <p class="intro">
          A calm, cat-loving FAQ with expandable answers. Open any question to learn a little more about feline habits, care, and behavior.
        </p>
      </section>
      <section class="faq-list" aria-label="Frequently asked questions">
        ${faqData.map(FAQItem).join("")}
      </section>
      <p class="signature">Made for curious humans and their very judgmental cats.</p>
    `;

    document.getElementById("maincontent").innerHTML = App();
  </script>
</body>
